sys_script.script:
(function executeRule(current, previous /*null when async*/) {
    try {
         // gs.info('- calling script inclue');
		// Create an instance of TaskPriorityCalc with the current record
        var calculator = new x_hsb11_hsbc_mss_o.TaskPriorityCalc(current);
        //gs.info('- called script inclue');
        // Calculate the priority
        var calculatedPriority = calculator.calculatePriority();

        // Log the calculated priority
        //gs.info( -From Business Rule: Calculated Priority = ' + calculatedPriority);

        // Update the dynamic priority field
        current.priority = calculatedPriority; // Ensure the field exists in the table
        //gs.info('New dynamic priority value set: ' + current.priority);

        // Save the updated record
        current.update();

    } catch (e) {
        // Log any errors that occur during execution
        gs.error('Error in Business Rule: ' + e.message);
    }
})(current, previous);
//call the scrippt include.cross scope//
